import{_ as e,o as t,c as a,a5 as o}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"WordPress 性能优化插件 — WP优化工具","description":"","frontmatter":{"标题":"WordPress 性能优化插件 — WP优化工具","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["CDN","JS延迟","SEO优化","WordPress","性能优化","懒加载","数据库优化","网站加速","谷歌字体"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"WP 瘦身模块","slug":"wp-瘦身模块","link":"#wp-瘦身模块","children":[]},{"level":3,"title":"速度优化模块","slug":"速度优化模块","link":"#速度优化模块","children":[{"level":4,"title":"CDN 管理","slug":"cdn-管理","link":"#cdn-管理","children":[]},{"level":4,"title":"预加载","slug":"预加载","link":"#预加载","children":[]},{"level":4,"title":"懒加载","slug":"懒加载","link":"#懒加载","children":[]},{"level":4,"title":"JavaScript 管理","slug":"javascript-管理","link":"#javascript-管理","children":[]}]},{"level":3,"title":"数据库优化模块","slug":"数据库优化模块","link":"#数据库优化模块","children":[]},{"level":3,"title":"中英双语界面","slug":"中英双语界面","link":"#中英双语界面","children":[]},{"level":3,"title":"模块化卡片式管理","slug":"模块化卡片式管理","link":"#模块化卡片式管理","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：进入管理界面","slug":"第二步-进入管理界面","link":"#第二步-进入管理界面","children":[]},{"level":3,"title":"第三步：配置各模块","slug":"第三步-配置各模块","link":"#第三步-配置各模块","children":[]},{"level":3,"title":"第四步：验证效果","slug":"第四步-验证效果","link":"#第四步-验证效果","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07-12）","slug":"v1-0-0-2026-07-12","link":"#v1-0-0-2026-07-12","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 性能优化插件 — WP优化工具.md","filePath":"md/wordpress主题插件/WordPress 性能优化插件 — WP优化工具.md"}'),n={name:"md/wordpress主题插件/WordPress 性能优化插件 — WP优化工具.md"};function s(l,r,i,g,d,h){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="wordpress-性能优化插件-—-wp优化工具" tabindex="-1">WordPress 性能优化插件 — WP优化工具 <a class="header-anchor" href="#wordpress-性能优化插件-—-wp优化工具" aria-label="Permalink to &quot;WordPress 性能优化插件 — WP优化工具&quot;">​</a></h1><blockquote><p>WordPress 综合性能优化工具集，集成 WP 瘦身、速度优化、数据库优化三大模块。通过禁用冗余功能、静态资源 CDN 加速、懒加载、JavaScript 延迟执行、数据库清理等多种手段，全方位提升网站加载速度和页面性能评分。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-33.png" alt=""></p><p>本插件是一款面向 WordPress 网站的全方位性能优化工具，围绕「减重、加速、清理」三个维度提供一站式优化方案。</p><p>插件在后台提供了模块化的卡片式管理界面，每个优化模块独立开关控制、配置即时生效。同时内置中英双语界面支持，可根据 WordPress 站点语言自动切换，也可手动指定语言。</p><p>插件通过输出缓冲（Output Buffering）技术在 PHP 层对页面 HTML 进行实时处理，实现静态资源 URL 重写、脚本延迟/推迟加载、图片/视频懒加载等功能，无需修改主题代码即可生效。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="wp-瘦身模块" tabindex="-1">WP 瘦身模块 <a class="header-anchor" href="#wp-瘦身模块" aria-label="Permalink to &quot;WP 瘦身模块&quot;">​</a></h3><p>禁用 WordPress 中不必要的功能和输出，从源头减少页面请求和服务器负载：</p><p>— <strong>禁用前端 Admin 栏</strong>：为所有用户移除前台页面顶部的黑色管理工具栏，给访客更干净的视觉体验，管理员仍可从后台访问；<br> — <strong>禁用 XML-RPC</strong>：完全阻止 XML-RPC 访问，防止暴力破解和 DDoS 攻击。注意：禁用后移动应用或远程工具将无法通过 XML-RPC 连接；<br> — <strong>禁用 RSS 源</strong>：从页面头部移除所有 RSS 和 Atom 订阅链接，对订阅 URL 返回 404。适用于不需要内容分发的展示型或静态网站；<br> — <strong>禁用 Self-pingbacks</strong>：阻止链接到自己文章时产生的自我引用通知，减少数据库冗余和通知噪音；<br> — <strong>禁用评论</strong>：全局禁用整个网站的评论系统，评论表单、已有评论列表和相关链接全部移除；<br> — <strong>移除 jQuery Migrate</strong>：从前端移除 jQuery Migrate 兼容脚本，减少一次 HTTP 请求；<br> — <strong>移除 WP 版本信息</strong>：从 HTML 头部、RSS 和脚本/CSS 查询字符串中移除版本号，防止自动化扫描器识别版本针对性攻击；<br> — <strong>移除 wlwmanifest 链接</strong>：移除 Windows Live Writer 清单链接，该旧式编辑器已不再开发维护；<br> — <strong>移除 RSD 链接</strong>：移除 Really Simple Discovery 链接，对现代 WordPress 已无必要；<br> — <strong>移除短链</strong>：从 HTML 头部移除短链接 meta 标签（如 ?p=123），启用美化固定链接后完全冗余；<br> — <strong>移除 REST API 链接</strong>：从页面头部移除 REST API 发现链接，仅移除外宣链接不会禁用 REST API 本身；<br> — <strong>限制文章修订版本</strong>：可设置每篇文章最大修订存储数量，推荐 3-5 个，设为 0 完全禁用修订；<br> — <strong>Heartbeat 控制</strong>：可选择禁用或仅限文章编辑器使用 Heartbeat API，减少后台 AJAX 轮询请求，显著降低服务器 CPU 和数据库负载；<br> — <strong>Gravatar 镜像</strong>：支持将默认 Gravatar.com 替换为国内镜像地址，加速头像加载，对国内网站特别有益；<br> — <strong>谷歌字体管理</strong>：提供禁用谷歌字体、添加 display=swap 属性防止文字不可见（FOIT）、CDN 镜像加速、本地化托管及清除本地缓存共五种处理方式。</p><h3 id="速度优化模块" tabindex="-1">速度优化模块 <a class="header-anchor" href="#速度优化模块" aria-label="Permalink to &quot;速度优化模块&quot;">​</a></h3><h4 id="cdn-管理" tabindex="-1">CDN 管理 <a class="header-anchor" href="#cdn-管理" aria-label="Permalink to &quot;CDN 管理&quot;">​</a></h4><p>— <strong>启用 CDN</strong>：将 CSS、JS、图片、字体等静态资源的 URL 重写为 CDN 域名，通过全球边缘节点分发文件，大幅降低远离源站访客的访问延迟；<br> — <strong>CDN 地址</strong>：设定 CDN 基础域名（如 <a href="https://cdn.example.xn--com" target="_blank" rel="noreferrer">https://cdn.example.com），自动替换匹配资源的原始域名；</a>,;-tg4jn1bi0ap5am6zxxf1l0b8tkhu1a0g2afr4bwy4b09p/)<br> — <strong>CDN 包含目录</strong>：支持自定义通过 CDN 的目录范围，默认 wp-content 和 wp-includes；<br> — <strong>CDN 排除列表</strong>：支持按文件名或模式排除特定文件不经过 CDN，适用于必须保留在源站的动态资源。</p><h4 id="预加载" tabindex="-1">预加载 <a class="header-anchor" href="#预加载" aria-label="Permalink to &quot;预加载&quot;">​</a></h4><p>— <strong>Instant Page</strong>：使用 Instant Page 库实现即时页面预加载，访客光标悬停在链接上超过 65ms 时，浏览器后台预取该页面，点击时几乎瞬间加载；<br> — <strong>DNS 预取</strong>：在页面头部添加 DNS 预取提示，让浏览器提前解析第三方域名，每次连接可节省 20-120ms；<br> — <strong>预连接</strong>：提前与目标域名建立完整连接（DNS + TCP + TLS），进一步减少跨域资源加载延迟；<br> — <strong>关键图片预加载</strong>：为页面顶部指定数量的图片添加 preload 链接头，在 HTML 解析完成前即开始下载首屏图片，改善最大内容绘制（LCP）指标；<br> — <strong>资源预加载</strong>：支持指定脚本、样式、字体等资源进行预加载，可按设备类型和页面位置精细控制。</p><h4 id="懒加载" tabindex="-1">懒加载 <a class="header-anchor" href="#懒加载" aria-label="Permalink to &quot;懒加载&quot;">​</a></h4><p>— <strong>图片懒加载</strong>：仅在图片即将滚动进入视口时才加载，而非页面加载时一次性全部加载，显著减少初始页面重量和带宽消耗；<br> — <strong>框架/视频懒加载</strong>：推迟加载 iframe 内容（YouTube 视频、Google 地图、第三方小部件），直到用户滚动到附近；<br> — <strong>YouTube 预览缩略图</strong>：将 YouTube 视频嵌入替换为静态预览缩略图，仅在访客点击后才加载完整播放器，显著加速含大量嵌入视频的页面；<br> — <strong>监听新 DOM</strong>：持续监控动态注入的元素（AJAX 内容、弹窗、无限滚动），自动对新插入的图片/iframe 应用懒加载；<br> — <strong>修复图片尺寸</strong>：自动检测并补充缺失的宽高属性，防止图片加载时导致布局偏移（CLS）；<br> — <strong>图片淡入效果</strong>：懒加载图片进入视口后应用平滑 CSS 淡入过渡，取代突兀的视觉弹出；<br> — <strong>跳过前 N 张图片</strong>：设置首屏直接加载（不懒加载）的图片数量，默认 5 张，保证首屏加载速度；<br> — <strong>视口阈值</strong>：可调节图片开始预加载时距离视口下方的像素距离，平衡流畅度与带宽消耗；<br> — <strong>排除列表</strong>：支持按 CSS 类名或图片 URL 模式排除特定图片不进行懒加载。</p><h4 id="javascript-管理" tabindex="-1">JavaScript 管理 <a class="header-anchor" href="#javascript-管理" aria-label="Permalink to &quot;JavaScript 管理&quot;">​</a></h4><p>— <strong>推迟 JavaScript</strong>：为所有 script 标签添加 defer 属性，脚本并行下载不阻塞 HTML 解析，仅在 DOM 构建完成后执行；<br> — <strong>包含 jQuery 推迟</strong>：在启用 defer 时是否同时对 jQuery 应用推迟，注意部分主题可能因 jQuery 推迟而出错；<br> — <strong>推迟排除列表</strong>：支持按脚本句柄（如 jquery, contact-form-7）排除特定脚本不进行推迟；<br> — <strong>延迟 JavaScript</strong>：将 JS 执行延迟到用户首次交互（鼠标移动、滚动、触摸）之后，大幅改善可交互时间（TTI）；<br> — <strong>延迟类型</strong>：支持「全部 JS」模式（所有脚本延迟到交互后）和「指定 JS」模式（仅延迟明确列出的脚本）；<br> — <strong>自定义 JS 注入</strong>：支持在页面头部、Body 开始、页脚三个位置插入自定义 JavaScript 代码。</p><h3 id="数据库优化模块" tabindex="-1">数据库优化模块 <a class="header-anchor" href="#数据库优化模块" aria-label="Permalink to &quot;数据库优化模块&quot;">​</a></h3><p>— <strong>数据统计面板</strong>：后台实时显示文章修订、自动草稿、回收站文章、垃圾评论、回收站评论、过期瞬态等数据当前数量；<br> — <strong>一键清理</strong>：勾选需要清理的项目后点击「立即优化」按钮，批量清理数据库冗余数据；<br> — <strong>清理选项</strong>：文章修订、自动草稿、回收站文章、垃圾评论、回收站评论、过期瞬态、所有瞬态、优化数据库表，共 8 个清理项；<br> — <strong>定期自动优化</strong>：支持关闭/每天/每周/每月四种定时计划，利用 WordPress Cron 自动执行勾选的清理任务；<br> — <strong>优化数据库表</strong>：执行 SQL OPTIMIZE TABLE 命令整理表碎片并回收空间，主要对 MyISAM 表有效。</p><h3 id="中英双语界面" tabindex="-1">中英双语界面 <a class="header-anchor" href="#中英双语界面" aria-label="Permalink to &quot;中英双语界面&quot;">​</a></h3><p>— 支持中文、英文及自动（跟随 WordPress 站点语言）三种语言模式；<br> — 后台顶部提供语言切换下拉框，切换即时生效；<br> — 所有设置项名称和功能说明均完整翻译，确保中英文用户操作无障碍。</p><h3 id="模块化卡片式管理" tabindex="-1">模块化卡片式管理 <a class="header-anchor" href="#模块化卡片式管理" aria-label="Permalink to &quot;模块化卡片式管理&quot;">​</a></h3><p>— 三大模块以独立卡片形式展示，每个模块带总开关，一键启用或停用整个模块；<br> — 模块内容区支持折叠展开，启用总开关后自动加载配置界面；<br> — 所有设置通过 AJAX 异步保存，无需刷新页面，保存成功即时提示。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>wpyhjs_tools</code> 文件夹上传至网站 <code>/wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「WP优化工具」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-34.png" alt=""></p><h3 id="第二步-进入管理界面" tabindex="-1">第二步：进入管理界面 <a class="header-anchor" href="#第二步-进入管理界面" aria-label="Permalink to &quot;第二步：进入管理界面&quot;">​</a></h3><p>启用后，WordPress 后台左侧菜单栏会出现「WP优化工具」菜单项。点击进入后可见三个模块卡片：</p><p>— <strong>WP瘦身</strong>：管理 WordPress 核心功能禁用和精简；<br> — <strong>速度优化</strong>：管理 CDN、预加载、懒加载和 JS 优化；<br> — <strong>数据库优化</strong>：管理数据库清理和定期优化。</p><h3 id="第三步-配置各模块" tabindex="-1">第三步：配置各模块 <a class="header-anchor" href="#第三步-配置各模块" aria-label="Permalink to &quot;第三步：配置各模块&quot;">​</a></h3><p>每个模块卡片右侧有总开关，点击开关启用模块后，卡片自动展开显示详细配置项：</p><p>— 各功能项配有独立开关和详细说明文字，按需开启或关闭；<br> — 带输入框的配置项（如 CDN 地址、排除列表、修订数量等）直接填写后点击「保存设置」按钮；<br> — 数据库模块支持先查看各项数据量，勾选需要清理的项目后点击「立即优化」执行清理。</p><h3 id="第四步-验证效果" tabindex="-1">第四步：验证效果 <a class="header-anchor" href="#第四步-验证效果" aria-label="Permalink to &quot;第四步：验证效果&quot;">​</a></h3><p>— 使用浏览器开发者工具（F12 → Network / Performance 面板）检查页面加载的请求数量和资源大小是否减少；<br> — 使用 PageSpeed Insights 或 Lighthouse 等工具对比优化前后的评分变化；<br> — 数据库优化模块的数据统计面板会实时更新清理后的数量。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件通过输出缓冲技术在 PHP 层对页面 HTML 进行实时处理，与大多数缓存插件兼容，但建议先在一个模块上测试确认无冲突后再全部启用；<br> — 不同 WordPress 主题和插件对 jQuery 的依赖方式各异，「推迟 JavaScript」和「包含 jQuery 推迟」选项开启后如发现页面功能异常，可使用排除列表将特定脚本排除；<br> — 「延迟 JavaScript」功能会推迟所有或指定脚本直到用户交互，开启后页面初始加载时交互元素可能暂时无响应，建议配合排除列表保留关键脚本；<br> — 谷歌字体「本地化」功能会将字体文件下载到插件目录下的缓存文件夹中，字体文件可能占用一定磁盘空间；<br> — 数据库「优化表」功能仅对 MyISAM 存储引擎的表有效，InnoDB 表不受影响；清理所有瞬态数据可能导致网站在缓存重新预热期间稍慢几分钟；<br> — CDN 功能仅对页面中的静态资源 URL 进行重写，不会上传文件到 CDN 服务商，您需要自行在 CDN 服务商处配置回源。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a><br> — 授权：不限制网站数量，下载安装后永久免费使用</p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-12" tabindex="-1">v1.0.0（2026-07-12） <a class="header-anchor" href="#v1-0-0-2026-07-12" aria-label="Permalink to &quot;v1.0.0（2026-07-12）&quot;">​</a></h3><p>— 首次发布；<br> — WP 瘦身模块：实现 15 项 WordPress 核心功能禁用与精简，包括 Admin 栏、XML-RPC、RSS、评论、jQuery Migrate、版本信息、谷歌字体管理等；<br> — 速度优化模块：CDN 静态资源 URL 重写、Instant Page 预加载、DNS 预取/预连接、图片懒加载、YouTube 预览缩略图、图片尺寸修复与淡入效果、JS 推迟/延迟加载、自定义 JS 注入；<br> — 数据库优化模块：文章修订/自动草稿/回收站/垃圾评论等 8 项清理功能、数据统计面板、一键优化按钮、定时自动清理（每天/每周/每月）；<br> — 中英双语界面支持，自动/手动语言切换；<br> — 模块化卡片式管理界面，AJAX 异步保存，无需刷新页面。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3060.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3060.html</a></p>',48)])])}const p=e(n,[["render",s]]);export{c as __pageData,p as default};
